@source "../";

/* Sheet and Invoice preserve their distinct upstream cell utilities under host prose. */
.graph-frame.graph-frame .graph-sheet-table,
.graph-frame.graph-frame .graph-invoice-table {
  display: table;
  border-collapse: separate;
  border-spacing: 0;
  margin: 0;
  overflow: visible;
}
.graph-frame.graph-frame .graph-sheet-table tr,
.graph-frame.graph-frame .graph-sheet-table th,
.graph-frame.graph-frame .graph-sheet-table td,
.graph-frame.graph-frame .graph-invoice-table tr,
.graph-frame.graph-frame .graph-invoice-table th,
.graph-frame.graph-frame .graph-invoice-table td {
  border: 0;
  background: transparent;
  font-size: inherit;
}
.graph-frame.graph-frame .graph-sheet-table th,
.graph-frame.graph-frame .graph-sheet-table td,
.graph-frame.graph-frame .graph-invoice-table th,
.graph-frame.graph-frame .graph-invoice-table td {
  padding: revert-layer;
  color: revert-layer;
  font-weight: revert-layer;
  text-align: revert-layer;
  line-height: revert-layer;
}

.graph-frame .graph-scroll-x:focus-visible {
  outline-offset: 3px;
}

/* Preserve native table layout and graph geometry under host prose styles. */
.graph-frame.graph-frame .graph-table {
  display: table;
  border-collapse: separate;
  border-spacing: 0;
  margin: 0;
  overflow: visible;
}
.graph-frame.graph-frame .graph-table tr,
.graph-frame.graph-frame .graph-table th,
.graph-frame.graph-frame .graph-table td {
  border: 0;
  background: transparent;
  font-size: inherit;
}
.graph-frame.graph-frame .graph-table th {
  color: var(--foreground);
  font-weight: 400;
  padding: 0 0.75rem 0.75rem;
}
.graph-frame.graph-frame .graph-table tbody td {
  padding: 0.625rem 0.75rem;
}
.graph-frame.graph-frame .graph-table tfoot td {
  padding: 0.25rem 0.75rem 0;
}
.graph-frame.graph-frame .graph-table th.text-right {
  text-align: right;
}
.graph-frame.graph-frame .graph-table th.text-left {
  text-align: left;
}
.graph-frame.graph-frame .graph-table thead tr[aria-hidden] th {
  padding: 0;
}
.graph-frame.graph-frame .graph-table tfoot tr[aria-hidden] td {
  padding: 0.5rem 0 0.75rem;
}

/* Labeled graphs carry their own geometry and palette utilities on native cells. */
.graph-frame.graph-frame .graph-labeled-table th,
.graph-frame.graph-frame .graph-labeled-table tbody td {
  padding: revert-layer;
  color: revert-layer;
  text-align: revert-layer;
  line-height: revert-layer;
}
.graph-frame.graph-frame .graph-labeled-table thead tr[aria-hidden] th {
  padding: 0;
}
.graph-frame.graph-frame .graph-labeled-table th.text-left,
.graph-frame.graph-frame .graph-labeled-table th.text-right {
  text-align: revert-layer;
}

/* Unlayered host prose rules must not change graph list geometry. */
.graph-frame.graph-frame ul,
.graph-frame.graph-frame ol {
  list-style: none;
  margin: revert-layer;
  padding: 0;
}
.graph-frame.graph-frame li + li {
  margin: revert-layer;
}

/* Discard the unlayered host values so layered utilities and preflight win. */
.graph-frame.graph-frame p {
  margin: revert-layer;
  line-height: revert-layer;
}
/* Quote supplies its own frame, spacing and text color. */
.graph-frame.graph-frame blockquote {
  margin: revert-layer;
  border-left: 0;
  padding: revert-layer;
  color: inherit;
  transition: none;
}
.graph-frame.graph-frame a,
.graph-frame.graph-frame a:hover {
  color: revert-layer;
  font-weight: revert-layer;
  text-decoration: revert-layer;
  text-underline-offset: revert-layer;
  transition: revert-layer;
}
.graph-frame.graph-frame code,
.graph-frame.graph-frame a:hover > code {
  color: revert-layer;
  font-size: revert-layer;
  border-radius: revert-layer;
  padding: revert-layer;
  background-color: revert-layer;
  transition: revert-layer;
}

@utility graph-title-ink {
  background-image: var(--graph-title-gradient, none);
  -webkit-background-clip: text;
  background-clip: text;
  color: var(--graph-title-color, var(--graph-accent));

  /* Keep gradient ink above the accompanying Tailwind text color utility. */
  &.text-graph-accent {
    color: var(--graph-title-color, var(--graph-accent));
  }
}
@utility graph-frame {
  background-image:
    repeating-linear-gradient(to right, var(--graph-frame) 0 2px, transparent 2px 7px),
    repeating-linear-gradient(to bottom, var(--graph-frame) 0 2px, transparent 2px 7px),
    repeating-linear-gradient(to right, var(--graph-frame) 0 2px, transparent 2px 7px),
    repeating-linear-gradient(to bottom, var(--graph-frame) 0 2px, transparent 2px 7px);
  background-repeat: repeat-x, repeat-y, repeat-x, repeat-y;
  background-position:
    0 0,
    100% 0,
    0 100%,
    0 0;
  background-size:
    100% 1px,
    1px 100%,
    100% 1px,
    1px 100%;
}

@utility graph-rule {
  height: 1px;
  background-image: repeating-linear-gradient(
    to right,
    var(--graph-frame) 0 2px,
    transparent 2px 7px
  );
}

@utility graph-rule-y {
  width: 1px;
  background-image: repeating-linear-gradient(
    to bottom,
    var(--graph-frame) 0 2px,
    transparent 2px 7px
  );
}

@utility scrollbar-none {
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

@utility scrollbar-graph {
  scrollbar-width: thin;
  scrollbar-color: var(--graph-frame) transparent;

  &::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  &::-webkit-scrollbar-track {
    background: transparent;
  }

  &::-webkit-scrollbar-thumb {
    background-color: var(--graph-frame);
    border-radius: 0;
  }

  @media (hover: hover) and (pointer: fine) {
    &::-webkit-scrollbar-thumb:hover {
      background-color: var(--graph-muted);
    }
  }
}

@utility graph-scroll-x {
  position: relative;
  overflow-x: auto;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

