}

@layer base {
  :root {
    --graph-accent: oklch(0.5 0.14 228);
    --graph-accent-2: oklch(0.48 0.18 259);
    --graph-accent-3: oklch(0.5 0.14 248);
    --graph-frame: oklch(0.72 0 0);
    --graph-muted: oklch(0.48 0 0);
    --graph-faint: oklch(0.82 0 0);
  }
  .dark {
    --graph-accent: oklch(0.77 0.15 228);
    --graph-accent-2: oklch(0.68 0.18 259);
    --graph-accent-3: oklch(0.72 0.15 248);
    --graph-frame: oklch(0.48 0 0);
    --graph-muted: oklch(0.68 0 0);
    --graph-faint: oklch(0.28 0 0);
  }
}

